/**
 * GET /api/sections/thumbnail/<id>
 *
 * Returns a thumbnail image for one section.
 *
 * Sprint 1a (now): SVG card with section accent + category icon + name
 *   — visually scannable in the palette, no Playwright needed.
 * Sprint 1b (next commit): real PNG screenshot generated by Playwright
 *   against a live running generated app. Cached PNGs at
 *   apps/studio/public/thumbnails/<id>.png — if present they win.
 *
 * Cache header set to 1 day for SVGs (regenerate cheap if catalog adds
 * sections). PNG cache served by Next's static-file middleware.
 */
import { NextResponse } from 'next/server'
import { readFile, stat } from 'node:fs/promises'
import { resolve } from 'node:path'
import { parse as parseYaml } from 'yaml'

const PROJECT_ROOT = resolve(process.cwd(), '..', '..')
const SECTIONS_DIR = resolve(PROJECT_ROOT, 'sections')
const PUBLIC_THUMBS = resolve(process.cwd(), 'public', 'thumbnails')

type Params = { params: Promise<{ id: string }> }

/** Loose lookup: scan sections/<category>/<id>/section.yaml until match. */
async function findSection(id: string): Promise<{ id: string; displayName: string; description?: string; category: string; tags?: string[] } | null> {
  const { readdir } = await import('node:fs/promises')
  let cats: string[]
  try {
    cats = (await readdir(SECTIONS_DIR, { withFileTypes: true }))
      .filter((e) => e.isDirectory())
      .map((e) => e.name)
  } catch {
    return null
  }
  for (const cat of cats) {
    try {
      const yamlPath = resolve(SECTIONS_DIR, cat, id, 'section.yaml')
      const raw = await readFile(yamlPath, 'utf-8')
      const m = parseYaml(raw) as Record<string, unknown>
      return {
        id: String(m.id ?? id),
        displayName: String(m.displayName ?? id),
        description: m.description ? String(m.description) : undefined,
        category: cat,
        tags: Array.isArray(m.tags) ? (m.tags as string[]) : undefined,
      }
    } catch {
      continue
    }
  }
  return null
}

