    cta: { accent: '#ec4899', emoji: '👉', gradient: ['#ec4899', '#f97316'] },
    footer: { accent: '#64748b', emoji: '⬇', gradient: ['#475569', '#1e293b'] },
    header: { accent: '#0ea5e9', emoji: '⬆', gradient: ['#0ea5e9', '#6366f1'] },
    testimonials: { accent: '#facc15', emoji: '⭐', gradient: ['#facc15', '#f97316'] },
