    faq: { accent: '#06b6d4', emoji: '❓', gradient: ['#06b6d4', '#3b82f6'] },
    gallery: { accent: '#f97316', emoji: '🖼', gradient: ['#f97316', '#ec4899'] },
    stats: { accent: '#10b981', emoji: '📊', gradient: ['#10b981', '#06b6d4'] },
    team: { accent: '#8b5cf6', emoji: '👥', gradient: ['#8b5cf6', '#a855f7'] },
    content: { accent: '#475569', emoji: '📝', gradient: ['#475569', '#0f172a'] },
